@xfail_if_triton_cpu
def test_round(self):
    def fn(a, b):
        return torch.round(a), torch.round(b + 1), torch.round(a, decimals=2)

    # without manual_seed, there is some chance this test fails due to:
    # https://github.com/triton-lang/triton/issues/530
    torch.manual_seed(0)

    # with *100 we are always getting a number exactly at .5 which we don't do right in half
    self.common(fn, (torch.randn(8, 8) * 100, torch.randn(8, 8) * 10))

@xfail_if_triton_cpu
def test_round_correctness(self):
    if self.device == "cuda":
        raise unittest.SkipTest("need to debug tl.libdevice on A100/V100")

    def fn(a):
        return torch.round(a)

    dtype = highest_precision_float(self.device)
    self.common(
        fn,
        [torch.arange(-10, 10, 0.1, dtype=dtype)],
        check_lowp=False,
    )

@xfail_if_triton_cpu
def test_builtins_round(self):
    def fn(x, i):
        return x[: round(i / 2 + 1)] + round(i / 2)

    cfn = torch.compile(fullgraph=True, dynamic=True)(fn)

    x = torch.zeros(5, dtype=torch.int, device=self.device)
    with torch.no_grad():
        for i in range(1, 6):
            self.assertEqual(cfn(x, i), fn(x, i))

@xfail_if_triton_cpu
def test_builtins_round_float_ndigits_pos(self):
    def fn(x, i):
        return x + round(i / 2 * 123.4567, 1)

    cfn = torch.compile(fullgraph=True, dynamic=True)(fn)

    x = torch.zeros(2, device=self.device)
    i = 2

    with torch.no_grad():
        self.assertEqual(cfn(x, i), fn(x, i))

